// APP_DB_HOST -> db.host, APP_LOG_LEVEL -> logLevel, APP_PORT -> port
const ENV_MAP = {
  APP_PORT: 'port',
  APP_DEBUG: 'debug',
  APP_LOG_LEVEL: 'logLevel',
  APP_DB_HOST: 'db.host',
  APP_DB_PORT: 'db.port',
  APP_DB_POOL: 'db.pool',
  APP_DB_SSL: 'db.ssl',
};

