      start = idx;
    }

    const pageItems = all.slice(start, start + pageSize);

    let nextCursor = null;
    if (pageItems.length === pageSize && start + pageSize < all.length) {
      const last = pageItems[pageItems.length - 1];
      nextCursor = encodeCursor({ createdAt: last.createdAt, id: last.id });
    } else {
      nextCursor = null;
    }

