// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: statement.mjs (late fees - half-up is written into the customer
 * agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even), symmetric for negatives.
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4
 * Used by: invoice.mjs (line tax)
 */
export function roundCentsEven(x) {
  if (x === 0) return 0;
  const sign = Math.sign(x);
  const abs = Math.abs(x);
  const floor = Math.floor(abs);
  const frac = abs - floor;
  const eps = 1e-12;
  let resultAbs;
  if (Math.abs(frac - 0.5) < eps) {
    resultAbs = floor % 2 === 0 ? floor : floor + 1;
  } else if (frac < 0.5) {
    resultAbs = floor;
  } else {
    resultAbs = floor + 1;
  }
  if (resultAbs === 0) return 0;
  return sign * resultAbs;
}

