```mjs
// src/lru.mjs
// Least-recently-used map. Iteration order of `this.map` is oldest -> newest.
export class LRU {
  constructor({ max = 100, onEvict } = {}) {
    if (!(max >= 1)) throw new RangeError('max must be >= 1');
    this.max = max;
    this.map = new Map();
    this.hits = 0;
    this.misses = 0;
    this.onEvict = typeof onEvict === 'function' ? onEvict : undefined;
  }

  get size() {
    return this.map.size;
  }

  has(key) {
    return this.map.has(key);
  }

  /** Read without touching recency or stats. */
  peek(key) {
    return this.map.get(key);
  }

  get(key) {
    if (!this.map.has(key)) {
      this.misses++;
      return undefined;
    }
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value);
    this.hits++;
    return value;
  }

  _emit(key, value, reason) {
    if (!this.onEvict) return;
    try {
      const r = this.onEvict(key, value, reason);
      if (r && typeof r.then === 'function') {
        r.catch(() => {});
      }
    } catch {
      // preserve LRU invariants even if hook throws
    }
  }

  set(key, value) {
    if (this.map.has(key)) {
      // update, not eviction – must not fire hook
      this.map.delete(key);
    }
    this.map.set(key, value);
    while (this.map.size > this.max) {
      const oldestKey = this.map.keys().next().value;
      const oldestVal = this.map.get(oldestKey);
      this.map.delete(oldestKey);
      this._emit(oldestKey, oldestVal, 'capacity');
    }
    return this;
  }

  delete(key) {
    if (!this.map.has(key)) return false;
    const value = this.map.get(key);
    this.map.delete(key);
    this._emit(key, value, 'delete');
    return true;
  }

  clear() {
    if (this.map.size === 0) return;
    const entries = [...this.map.entries()];
    this.map.clear();
    for (const [k, v] of entries) {
      this._emit(k, v, 'clear');
    }
  }

  /** Keys from least to most recently used. */
  keys() {
    return [...this.map.keys()];
  }

  stats() {
    return { size: this.map.size, max: this.max, hits: this.hits, misses: this.misses };
  }
}
