// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    const t = setTimeout(() => {
      cleanup();
      resolve();
    }, ms);

    const onAbort = () => {
      clearTimeout(t);
      cleanup();
      reject(signal.reason);
    };

    const cleanup = () => {
      signal?.removeEventListener('abort', onAbort);
    };

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

function cancellableSleep(ms, signal, sleepFn) {
  if (!signal) {
    // No signal: just call sleep, preserving sync-throw handling
    return (async () => {
      return await sleepFn(ms, signal);
    })();
  }

  if (signal.aborted) {
    return Promise.reject(signal.reason);
  }

  return new Promise((resolve, reject) => {
    let settled = false;

    const onAbort = () => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(signal.reason);
    };

    const cleanup = () => {
      signal.removeEventListener('abort', onAbort);
    };

    signal.addEventListener('abort', onAbort, { once: true });

    let result;
    try {
      result = sleepFn(ms, signal);
    } catch (e) {
      if (settled) return;
      settled = true;
      cleanup();
      reject(e);
      return;
    }

    Promise.resolve(result).then(
      (v) => {
        if (settled) return;
        settled = true;
        cleanup();
        resolve(v);
      },
      (e) => {
        if (settled) return;
        settled = true;
        cleanup();
        if (signal.aborted) {
          reject(signal.reason);
        } else {
          reject(e);
        }
      }
    );
  });
}

export async function retry(fn, opts = {}) {
  const {
    retries = 3,
    baseDelayMs = 100,
    factor = 2,
    sleep = defaultSleep,
    signal,
  } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  const effectiveRetries = Math.max(0, retries);
  let lastErr;

  for (let attempt = 0; attempt <= effectiveRetries; attempt++) {
    if (attempt > 0 && signal?.aborted) {
      throw signal.reason;
    }

    try {
      return await fn(attempt);
    } catch (err) {
      lastErr = err;

      if (signal?.aborted) {
        throw signal.reason;
      }

      if (err && err.retryable === false) {
        throw err;
      }

      if (attempt === effectiveRetries) {
        break;
      }

      const delay = baseDelayMs * Math.pow(factor, attempt);

      try {
        await cancellableSleep(delay, signal, sleep);
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }

  throw lastErr;
}
